L={}
L[51]=[
  ("पाठ-51 («लोहा हमारा मुख्य साथी») का सार क्या है?","इस पाठ में हमने जाना कि लोहा केवल एक धातु नहीं, बल्कि एक बड़ा परिवार है जिसके अलग-अलग सदस्य हैं","इस पाठ में हमने पिछले तीस पाठों (पाठ 51 से 79) के धातु-ज्ञान का पूरा निचोड़ पाँच गिरहों में समझा","गैस-वेल्डिंग का सिलेंडर भारी दबाव से भरा शांत दिखने वाला साथी है, जो सम्मान यानी नियम माँगता है","चिंगारी-जाँच वेल्डर की कसौटी है — ग्राइंडर की हल्की छुअन पर माइल्ड स्टील पीली फुलझड़ी छोड़ता है"),
  ("«लोहा हमारा मुख्य साथी» (पाठ-51) की आम ग़लती क्या है?","हर चमकती चीज़ को स्टेनलेस स्टील मान लेना: कई बार जस्ता-चढ़ा लोहा यानी जीआई भी चमकता है, पर वह असली स्टेनलेस स्टील नहीं होता","गरम बत्ती जलने पर मशीन बंद कर देना: जब मशीन ज़्यादा गरम होने की बत्ती दिखाए, तो हड़बड़ी में मशीन का मुख्य स्विच बंद न करें","कमज़ोर कड़ियों को छिपाना: अगर आपको प्रेशर गेज (Pressure Gauge) पढ़ना अभी भी कठिन लगता है, तो उसे \"देख लेंगे\" कहकर न छोड़ें","कसकर बंद की गई घुंडी के साथ सिलेंडर खोलना: बिना घुंडी ढीली किए सीधे सिलेंडर का वाल्व खोल देना सबसे आम और ख़तरनाक ग़लती है"),
  ("कौन-सी ग़लती «लोहा हमारा मुख्य साथी» वाले पाठ-51 में बताई गई?","ग़लत छड़ का इस्तेमाल: \"काम तो चल ही जाएगा\" सोचकर किसी भी छड़ से वेल्डिंग कर देना जोड़ को कमज़ोर बनाता है","चाय-गुटखे से थकान \"भगाना\" — ये काँटा छिपाते हैं, बैटरी नहीं चढ़ाते; ऊपर से गुटखा अपना अलग क़र्ज़ लिखता है","जोड़ाई छिपाने को उस पर मोटा ढेर चढ़ा देना — गाँठ ढँकती नहीं, बड़ी होती है; इलाज रीत में है, ढेर में नहीं","नीचे बच्चों/राहगीरों का खड़े रहना — काम रोककर पहले घेरा; ऊपर से बरसती चिंगारी के नीचे तमाशबीन नहीं चाहिए"),
  ("«लोहा हमारा मुख्य» (पाठ-51) की सावधानी क्या है?","अनजान धातु पर पहला क़दम: अगर धातु की पहचान पक्की न हो, तो सीधे मुख्य हिस्से पर वेल्डिंग न करें","उँगलियों को बचाएँ: जब वायर-फीडर के पहिए घूम रहे हों, तो उसके भीतर कभी भी उँगली या पेचकस न डालें","तेल/पेट्रोल/डीज़ल रही टंकी — विशेषज्ञ-जाँच और पूरी सफ़ाई-प्रमाण के बिना उस पर टाँका बिलकुल नहीं","बाज़ार के ताज़ा भाव खुद पता करें: इस पाठ में हमने जान-बूझकर किसी मशीन का पक्का दाम नहीं लिखा है"),
  ("तेज़-दोहराव: पाठ-51 («लोहा हमारा मुख्य») का एक सूत्र?","लोहा = वेल्डर की मिट्टी","सिलेंडर सम्मान माँगता है","पहले 5 मिनट सबसे क़ीमती","थके हाथ की ना = कारीगरी"),
]
L[52]=[
  ("पाठ-52 («माइल्ड स्टील वेल्डर की») का सार क्या है?","माइल्ड स्टील वेल्डर की रोज़ी है — गाँव-क़स्बे का नब्बे फ़ीसदी काम इसी पर चलता है","इस पाठ में हमने सीखा कि बाज़ार में मिलने वाले नक़ली वेल्डिंग सामान से कैसे बचें","होल्डर दिन भर हथेली में रहने वाला चिमटा है — बिजली और आपके बीच की आख़िरी दीवार","आज हमने वेल्डिंग की सबसे नफ़ीस विधा — टीआईजी (TIG) वेल्डिंग का पहला परिचय पाया"),
  ("«माइल्ड स्टील वेल्डर की» (पाठ-52) की आम ग़लती क्या है?","\"आम लोहा ही तो है\" कहकर इसकी क़द्र न करना — रोज़ी की धातु की समझ ही सबसे पहले पक्की चाहिए","सुर याद किए बिना सिर्फ़ नाम रटना — सुर कान से बैठता है, कॉपी से नहीं; असली चाप ज़रूर सुनिए","पतले लोहे पर बहुत मोटी छड़ चलाना: इससे लोहा तुरंत कटकर बह जाता है और काम ख़राब हो जाता है","एक ही पर्ची थमाना — विकल्प के बिना ग्राहक फ़ैसले का साथी नहीं, सिर्फ़ भुगतानकर्ता रहता है"),
  ("कौन-सी ग़लती «स्टील वेल्डर की रोज़ी» वाले पाठ-52 में बताई गई?","चुंबक साथ न रखना — दो सेकंड की जाँच छोड़कर घंटों का पछतावा मोल लेना","जंग-रंग-तेल के ऊपर क्लैंप — छुआ है, जुड़ा नहीं; पहले रेती की दो रगड़","\"गरमी बहुत है, बनियान में कर लेता हूँ।\" — किरण को मौसम से मतलब नहीं","\"थोड़ी देर का ही तो ग्राइंडर है।\" — बूँद भी थोड़ी देर की ही होती है"),
  ("«माइल्ड स्टील वेल्डर» (पाठ-52) की सावधानी क्या है?","माइल्ड स्टील नरम है, पर उसकी कटी हुई धार और किनारे उतने ही तीखे हैं — दस्ताने का नियम (पाठ-4) धातु देखकर ढीला नहीं पड़ता","घटिया निकला माल कभी भी ऐसे कामों में इस्तेमाल न करें जहाँ जान का जोखिम हो (जैसे झूला, सीढ़ी, छत की रेलिंग, या भारी छज्जा)","सरिये का बँधा लच्छा-बंडल खोलते समय सिरे कमानी की तरह झटके से उछलते हैं — चेहरा हटाकर, दस्ताने पहनकर, बंधन आख़िर में काटिए","कान-रक्षा (पाठ-12) से समझौता कभी नहीं — और यह उल्टी समझ निकाल दीजिए कि \"सुनने के लिए रक्षक उतारना पड़ेगा\": अच्छा कान-रक्षक"),
  ("तेज़-दोहराव: पाठ-52 («माइल्ड स्टील वेल्डर») का एक सूत्र?","90% काम यही धातु","नीचे पटरा-तकिया","थकी बाँह = रुको","बुख़ार = डॉक्टर"),
]
L[53]=[
  ("पाठ-53 («लोहे की मोटाई गेज») का सार क्या है?","मोटाई की दो भाषाएँ हैं — मिलीमीटर सीधी (अंक बड़ा = मोटा) और गेज उलटी (अंक बड़ा = पतला)","गैस वेल्डिंग में लौ को पहचानना और उसे नियंत्रित करना ही एक कुशल कारीगर की असली पहचान है","पायलट हज़ार उड़ानों के बाद भी सूची से जाँचता है, क्योंकि याददाश्त थकती है और सूची नहीं","चिंगारी बीज है और जलने वाली चीज़ खेत — बीज रुक नहीं सकता, पर खेत हटाना आपके हाथ में है"),
  ("«लोहे की मोटाई गेज» (पाठ-53) की आम ग़लती क्या है?","आँख से मोटाई का दावा — रंगी-चढ़ी चादर आँख को मोटी दिखती है","तौल-मिलान कभी न करना — कच्ची तौल चुपचाप महीनों खाती रहती है","खुले-बरसाती काम में एक-किनारा सिलाई — साल भर बाद फूला जोड़","अंदाज़े से काम करना: \"मेरी आँख ही गुनिया है\" कहना बंद करें"),
  ("कौन-सी ग़लती «मोटाई गेज और मिलीमीटर» वाले पाठ-53 में बताई गई?","गेज और मिलीमीटर को आपस में मिला देना — दो भाषाएँ हैं, अनुवाद सोच-समझकर","\"धातु ही तो है\" कहकर आम छड़ से हाथ डाल देना — हैंडल वाली कहानी याद रखिए","नोक नीचे की ओर झुकाना — धक्का माल को और नीचे धकेलता है, दौड़ वहीं हारी","\"झनझनाहट हल्की है, चलता है।\" — हल्की झनझनाहट बड़ी रिसन की पहली बूँद है"),
  ("«लोहे की मोटाई» (पाठ-53) की सावधानी क्या है?","भाव तय करते समय पुर्ज़ी पर मोटाई लिखवा लीजिए — बाद के झगड़े की जड़ यहीं कटती है","चिंगारी-जाँच है तो ग्राइंडर-काम ही — चश्मा-दस्ताने-गार्ड बिना छूट के (पाठ-28)","त्वचा पर किरण की जलन हो जाए (लाल, तपती त्वचा) तो ठंडे साफ़ पानी से आराम दीजिए","कपड़ों में आग लग जाए तो दौड़िए मत — दौड़ने से हवा मिलती है और लपट बढ़ती है"),
  ("तेज़-दोहराव: पाठ-53 («लोहे की मोटाई») का एक सूत्र?","मिलीमीटर सीधी भाषा","चढ़ाई ≥ चौड़ी उँगली","पायँचा जूते के ऊपर","रुई शोर नहीं रोकती"),
]
L[54]=[
  ("पाठ-54 («ज़ंग लोहे का रोग») का सार क्या है?","ज़ंग लोहे का एक ऐसा रोग है जो नमी और हवा के मिलने से पैदा होता है","किनारे का जोड़ परिवार का शांत बंदी-कारीगर है — दो टुकड़े बग़ल-बग़ल","वेल्डर की कमर उसकी आधी पूँजी है, और ग़लत उठान उसका सबसे चुप दुश्मन","रंगे लोहे पर वेल्डिंग करना जोड़ और सेहत दोनों के लिए ख़तरनाक है"),
  ("«ज़ंग लोहे का रोग» (पाठ-54) की आम ग़लती क्या है?","\"रंग तो ग्राहक कराएगा\" कहकर नंगा लोहा सौंपना: कुछ वेल्डर काम पूरा करके बिना रंग या प्राइमर (Primer) लगाए ही ढाँचा ग्राहक को दे","दस्ताने वाले हाथ से पपड़ी झाड़ना: कई वेल्डर चिपिंग हथौड़ा मारने के बाद बची हुई धूल को अपने दस्ताने वाले हाथ से ही पोंछ देते हैं","\"जगह घेरता है\" कहकर हर हफ़्ते सब फेंक देना: कुछ कारीगर रोज़-रोज़ की सफ़ाई के चक्कर में हर छोटे टुकड़े को नाली या कचरे में फेंक","टैक के बाद सीध-जाँच छोड़कर सीधी भराई — दो सेकंड की अदालत टालने वाला दो घंटे की सज़ा काटता है (पाठ-93 में यह कहानी पूरी मिलेगी)"),
  ("कौन-सी ग़लती «ज़ंग लोहे का रोग» वाले पाठ-54 में बताई गई?","गीले लोहे पर वेल्डिंग: सुबह की ओस या बारिश से भीगे लोहे पर सीधे वेल्डिंग करने से जोड़ में हवा के बुलबुले बन जाते हैं","हर काम के लिए एक ही मशीन को बेस्ट मानना: यह सोचना कि टिग वेल्डिंग सबसे महँगी है तो वह हर काम के लिए सबसे अच्छी होगी","पानी डालकर ठंडा करना: वेल्डिंग के तुरंत बाद इसे ठंडा करने के लिए इस पर पानी डाल देना इसे पूरी तरह बर्बाद कर देता है","पुराने पाठों को भूल जाना — वेल्डिंग करते समय बार-बार पाठ 51 से 79 के नियम काम आएँगे, उन्हें दिमाग से ओझल न होने दें"),
  ("«ज़ंग लोहे का» (पाठ-54) की सावधानी क्या है?","जब आप तार-ब्रश या ग्राइंडर से ज़ंग साफ़ करते हैं, तो लोहे का बारीक चूरा और ज़ंग की धूल हवा में उड़ती है","ईमानदार स्व-परीक्षा: जब आप नीचे दी गई परीक्षा या AI की परीक्षा हल करें, तो पीछे के पाठ खोलकर नक़ल न करें","खाने-दवा-बच्चों से छूने वाले काम में धातु-दर्जे पर मोल-भाव पूरी तरह बंद — वहाँ सस्ती पर्ची बनती ही नहीं","कड़ी रोशनी से आँखों का बचाव: टीआईजी (TIG) की आर्क से निकलने वाली पराबैंगनी किरणें बहुत ही तीखी होती हैं"),
  ("तेज़-दोहराव: पाठ-54 («ज़ंग लोहे का») का एक सूत्र?","नमी + हवा = ज़ंग का रोग","सिलेंडर सम्मान माँगता है","पहले 5 मिनट सबसे क़ीमती","थके हाथ की ना = कारीगरी"),
]
L[55]=[
  ("पाठ-55 («स्टेनलेस स्टील की पहचान») का सार क्या है?","स्टेनलेस स्टील अपनी अदृश्य सुरक्षा-परत के कारण ज़ंग से पूरी तरह सुरक्षित रहता है","केबल मशीन की नसें हैं और उनका पूरा शास्त्र तीन शब्दों में है — मोटाई, लंबाई, जोड़","माइल्ड स्टील वेल्डर की रोज़ी है — गाँव-क़स्बे का नब्बे फ़ीसदी काम इसी पर चलता है","इस पाठ में हमने सीखा कि बाज़ार में मिलने वाले नक़ली वेल्डिंग सामान से कैसे बचें"),
  ("«स्टेनलेस स्टील की पहचान» (पाठ-55) की आम ग़लती क्या है?","सिर्फ़ चमक देखकर भरोसा करना: कई बार माइल्ड स्टील को घिसकर या उस पर क्रोम की परत चढ़ाकर चमका दिया जाता है","अच्छे अंक पर माला छोड़ देना — ज्ञान का इम्तिहान आज हुआ; आदत का इम्तिहान बिजली, आग और थकान रोज़ लेते हैं","छपे अंक रटकर हमेशा के लिए मान लेना — तालिका-अंक नाप-दर-नाप बदलते हैं और भाव रोज़; पर्ची अपनी, भाव आज का","पतले सर्विस वायर (Service Wire) का उपयोग: लोड के हिसाब से तार पतला होने पर बिजली का बिल तो बढ़ता ही है"),
  ("कौन-सी ग़लती «स्टेनलेस स्टील की पहचान» वाले पाठ-55 में बताई गई?","कतरन को कचरा समझना: इसके टुकड़े बहुत क़ीमती होते हैं","सफ़ाई सिर्फ़ ऊपर वाली सतह की — मिलन दोनों सतहों का है","ज़िम्मेदार टी एक तरफ़ सिलना — एक कब्ज़े वाला दरवाज़ा","एक ही ओर लगातार टैक — खिंचाव की बुआई भराई से पहले ही"),
  ("«स्टेनलेस स्टील की» (पाठ-55) की सावधानी क्या है?","स्टेनलेस स्टील को काटने या घिसने के लिए हमेशा उसका अपना अलग ग्राइंडिंग व्हील (Grinding Wheel) रखें","पैनी धार से बचना: जब हम एंगल या चैनल को काटते हैं, तो उसके कटे हुए सिरे सुई की तरह पैने हो जाते हैं","सुरक्षा के सामान जैसे हेलमेट, ग्राइंडर पहिया और दस्तानों (Gloves) में नक़ली माल का जुआ कभी मत खेलिए","तेल और ग्रीस से तौबा: ऑक्सीजन रेगुलेटर और उसके गेज पर कभी भी तेल, मोबिल ऑयल या ग्रीस नहीं लगना चाहिए"),
  ("तेज़-दोहराव: पाठ-55 («स्टेनलेस स्टील की») का एक सूत्र?","ज़ंग-मुक्त सुरक्षा परत","पहले 5 मिनट सबसे क़ीमती","रास्ता हमेशा साफ़ रखें","तिकड़ी: करंट-चाल-झुकाव"),
]
L[56]=[
  ("पाठ-56 («एल्युमिनियम हल्का पर ज़िद्दी») का सार क्या है?","एल्युमिनियम अपनी हल्की और मज़बूत बनावट के कारण बहुत लोकप्रिय है, लेकिन वेल्डिंग के मामले में यह बेहद नखरेबाज़ है","इस पाठ में हमने सीखा कि इलेक्ट्रोड वेल्डिंग का वह जादुई हथियार है जो पिघलकर दो लोहे के टुकड़ों को एक कर देता है","इस पाठ में हमने सीखा कि ऑटो-डार्कनिंग हेलमेट हमारी आँखों की सुरक्षा के लिए एक बहुत ही आधुनिक और बेहतरीन ढाल है","कच्चा लोहा यानी कास्ट आयरन लोहे के परिवार का वह भारी और भंगुर सदस्य है जो मुड़ता नहीं, बल्कि सीधे टूट जाता है"),
  ("«एल्युमिनियम हल्का पर ज़िद्दी» (पाठ-56) की आम ग़लती क्या है?","लोहे जैसा भरोसा दिखाना: यह सोचना कि जो लोहे को जोड़ सकता है, वह बिना सीखे एल्युमिनियम को भी जोड़ लेगा","पतले सर्विस वायर (Service Wire) का उपयोग: लोड के हिसाब से तार पतला होने पर बिजली का बिल तो बढ़ता ही है","चालू मशीन में सफ़ाई या कसाव करना: कुछ लोग मशीन का स्विच ऑन रखते हुए ही पेचकश से टर्मिनल कसने लगते हैं","घुमाने का आलस — \"लिटाने में वक़्त लगेगा\" कहकर खड़े से लड़ना: लिटाने का वक़्त हमेशा झालर छीलने से सस्ता"),
  ("कौन-सी ग़लती «एल्युमिनियम हल्का पर ज़िद्दी» वाले पाठ-56 में बताई गई?","रंग बदलने का इंतज़ार करना: यह सोचना कि जब यह लाल होगा तब वेल्डिंग रोक दूँगा","\"टंकी को पानी से धो लिया, अब ठीक है।\" — एक बार धोने से भीतर की भाप नहीं मरती","मोटी पेंसिल या स्केच पेन का उपयोग: मोटी लकीर वेल्डिंग में भ्रम पैदा करती है","नाक से सूँघकर रिसाव ढूँढना: कई लोग सोचते हैं कि गैस लीक होगी तो महक आ जाएगी"),
  ("«एल्युमिनियम हल्का पर» (पाठ-56) की सावधानी क्या है?","जब भी एल्युमिनियम को घिसा जाता है, तो उसका बहुत महीन चूरा (Fine Dust) हवा में उड़ता है","अगले हिस्से (यंत्रों की पहचान) में हम मशीन के और पास जाएँगे — पुर्ज़े, बटन, छड़ें, सेटिंग","सीमा-रेखा पहचानें: इस पाठ में हमने केवल बाहरी केबल, होल्डर और क्लैंप की मरम्मत सीखी है","चिपककर छूटी छड़ का सिरा तपा हुआ है — ज़मीन पर सोच कर रखिए (पाठ-8), पैर के पास कभी नहीं"),
  ("तेज़-दोहराव: पाठ-56 («एल्युमिनियम हल्का पर») का एक सूत्र?","एल्युमिनियम = हल्का, सफ़ेद-चाँदी रंग, चुंबक-मुक्त और बिना चिंगारी वाला","पुराना बिना एवीआर वाला जनरेटर हो तो केवल भारी ट्रांसफार्मर मशीन चलाएं","अगली मंज़िल = धातुओं का साम्राज्य, जहाँ हमारे ये सारे औज़ार काम आएँगे","काटने का सही नियम = पहले लोहे को सुर्ख़-लाल गर्म करें, फिर लीवर दबाएँ"),
]
L[57]=[
  ("पाठ-57 («कच्चा लोहा कास्ट आयरन») का सार क्या है?","कच्चा लोहा यानी कास्ट आयरन लोहे के परिवार का वह भारी और भंगुर सदस्य है जो मुड़ता नहीं, बल्कि सीधे टूट जाता है","इस पाठ में हमने सीखा कि ऑटो-डार्कनिंग हेलमेट हमारी आँखों की सुरक्षा के लिए एक बहुत ही आधुनिक और बेहतरीन ढाल है","खड़ी रेखा के दो रास्ते हैं — आज का रास्ता ऊपर से नीचे उतरना: गुरुत्व के साथ की तेज़ चाल, पतला-चपटा साफ़ टाँका","गैस कटिंग टॉर्च वेल्डिंग की दुनिया का एक बहुत ही शक्तिशाली औज़ार है जो मोटे लोहे को बहुत आसानी से काट सकता है"),
  ("«कच्चा लोहा कास्ट आयरन» (पाठ-57) की आम ग़लती क्या है?","भारी होने को मज़बूती मान लेना: सबसे बड़ी ग़लती यह मानना है कि जो चीज़ भारी और मोटी है, वह कभी टूट नहीं सकती","अलग-अलग मोटाई के एंगल एक ही ढेर में मिला देना: इससे काम के समय सही टुकड़ा ढूँढने में बहुत समय बर्बाद होता है","\"पंखा चला दिया, हो गया।\" — दुकान के भीतर घुमाया गया पंखा धुआँ बाहर नहीं फेंकता, पूरी दुकान में बाँट देता है","बिना साफ़ किए वेल्डिंग करना: इसकी अदृश्य परत को बिना घिसे या रसायनों से साफ़ किए सीधे वेल्डिंग शुरू कर देना"),
  ("कौन-सी ग़लती «आयरन टूटने वाला भाई» वाले पाठ-57 में बताई गई?","पानी डालकर ठंडा करना: वेल्डिंग के तुरंत बाद इसे ठंडा करने के लिए इस पर पानी डाल देना इसे पूरी तरह बर्बाद कर देता है","दूसरे का हेलमेट बिना पट्टा कसे पहनना — ढीला हेलमेट टाँके के बीच सरकता है, और आदमी नंगी आँख से आर्क में झाँक बैठता है","हर काम के लिए एक ही मशीन को बेस्ट मानना: यह सोचना कि टिग वेल्डिंग सबसे महँगी है तो वह हर काम के लिए सबसे अच्छी होगी","पुराने पाठों को भूल जाना — वेल्डिंग करते समय बार-बार पाठ 51 से 79 के नियम काम आएँगे, उन्हें दिमाग से ओझल न होने दें"),
  ("«कच्चा लोहा कास्ट» (पाठ-57) की सावधानी क्या है?","पैने किनारे: जब भी कास्ट आयरन का कोई टूटा पुर्ज़ा आपके पास आए, तो उसके किनारे बहुत पैने और काँच जैसे तीखे होते हैं","वज़न-गणित औज़ार है, हथियार नहीं — दूसरे कारीगर का भेद ग्राहक के सामने खोलते समय ज़बान नपी रखिए: अपना हिसाब दिखाइए","मीटर का लोड बढ़वाना हो, कनेक्शन की श्रेणी (घरेलू से व्यावसायिक) बदलवानी हो, या मीटर ख़राब होने की शिकायत करनी हो","खड़े किनारों की मुंडेर छाती-आँख की सीध में आती है — छींटे सीधे ऊपर उछलते हैं: हेलमेट नीचे, गला-कवच ठीक (पाठ-3)"),
  ("तेज़-दोहराव: पाठ-57 («कच्चा लोहा कास्ट») का एक सूत्र?","मुड़ता नहीं, सीधे टूटता है","काम के अनुसार सही रूप चुनें","कमज़ोरी ज़ंग, कवच रंग-रोगन","रस्म की चार चौकियाँ: वर्दी"),
]
L[58]=[
  ("पाठ-58 («जस्ता चढ़ी चादर GI») का सार क्या है?","जीआई (GI) यानी जस्ता चढ़ी चादर लोहे को ज़ंग से बचाने के लिए बहुत बढ़िया है","सीधी लकीर वेल्डर की वर्णमाला का पहला अक्षर है, और उसकी कॉपी की लाइन चॉक-रेखा","धातु और वेल्डिंग छड़ की सही जोड़ी बनाना वेल्डिंग की सबसे बुनियादी जरूरत है","घटिया या नक़ली लोहा कारीगर की साख और ग्राहक की जान दोनों के लिए ख़तरनाक है"),
  ("«जस्ता चढ़ी चादर GI» (पाठ-58) की आम ग़लती क्या है?","\"दो मिनट का ही तो टाँका है\" कहना — कई कारीगर सोचते हैं कि थोड़े से धुएँ से क्या होगा","चालू मशीन में होल्डर यूँ ही फेंक देना — जहाँ छुएगा, वहीं चिंगारी; ठिकाना = सूखी खूँटी","सिर्फ़ लिखावट पर भरोसा — लिखावट हर भाषा में नहीं होती; रंग-आकार हर भाषा में होते हैं","ऊपर ताकती छड़ को बहुत ऊपर उठा देना — अब ऊपरी किनारा कटेगा; ढाल हल्की, पूरी करवट नहीं"),
  ("कौन-सी ग़लती «चमक के पीछे ज़हर» वाले पाठ-58 में बताई गई?","बाद में पेंट न करना — जस्ता घिसने के बाद लोहा नंगा हो जाता है","\"बाद में समेट लूँगा।\" — बाद कभी नहीं आता; अगला काम आ जाता है","पुरानी झुकी कलाई को \"सीधा\" मानना — शीशा-कैमरा ही सच बोलता है","\"कमीज़ पर थोड़ा डीज़ल ही तो लगा है।\" — थोड़ा ईंधन भी ईंधन है"),
  ("«जस्ता चढ़ी चादर» (पाठ-58) की सावधानी क्या है?","जीआई चादर को घिसते या काटते समय जो बारीक चूरा उड़ता है, वह भी हानिकारक है","कपड़ों में आग लग जाए तो दौड़िए मत — दौड़ने से हवा मिलती है और लपट बढ़ती है","बुख़ार, चक्कर, या किसी भी नशे में मशीन को हाथ नहीं — न अपनी, न किसी और की","हाथ-पैर पर गरम टुकड़ा गिरकर जल जाए तो — ठंडा साफ़ पानी, कम-से-कम दस मिनट"),
  ("तेज़-दोहराव: पाठ-58 («जस्ता चढ़ी चादर») का एक सूत्र?","चमक = जस्ता-परत","जाँच बंद मशीन पर","नीचे पटरा-तकिया","थकी बाँह = रुको"),
]
L[59]=[
  ("पाठ-59 («तांबा पीतल का परिचय») का सार क्या है?","तांबा और पीतल लोहे के कुनबे से बाहर के दो रंगीन पड़ोसी हैं","नीचे से ऊपर की चढ़ाई ज़िम्मेदार खड़े जोड़ों की शाही सड़क है","लोहा ख़रीदना वेल्डिंग के धंधे का सबसे महत्वपूर्ण हिस्सा है","ग्राइंडर वेल्डर का सबसे उपयोगी लेकिन सबसे ख़तरनाक औज़ार है"),
  ("«तांबा पीतल का परिचय» (पाठ-59) की आम ग़लती क्या है?","पीले रंग को देखते ही पीतल कह देना — पीला रंग चढ़ा लोहा भी वैसा ही दिखता है; चुंबक जेब में है ही","काले चश्मे में चिपिंग करना: वेल्डिंग हेलमेट या काले चश्मे को पहनकर चिपिंग करने की कोशिश न करें","झिरी ज़रूरत से बड़ी कर देना — बड़ा फ़ासला पतले माल में सीधे नीचे टपकता है (छेद-कथा पाठ-100 की)","टाँका चढ़ाई के बीचों-बीच ऊपर की सतह पर चला देना — सिलाई किनारे की रेखा पर होती है, पीठ पर नहीं"),
  ("कौन-सी ग़लती «तांबा पीतल का परिचय» वाले पाठ-59 में बताई गई?","तांबे की कतरन को लोहे के ढेर में मिला देना — कई गुना दाम कूड़े के भाव लुट जाता है","शोभा के काम में खुला कोना छोड़ देना — बाहर की घाटी-लकीर ग्राहक की आँख में चुभती है","ग्राहक के \"सस्ता\" सुनते ही छलनी उलटी चलाना — जेब से शुरू किया माल उल्टा निकलता है","साफ़ शीशा घिसने पर पूरा काला शीशा बदल देना — पैसे की बर्बादी; पहले ढकना-शीशा देखो"),
  ("«तांबा पीतल का» (पाठ-59) की सावधानी क्या है?","तांबे-पीतल की घिसाई का महीन चूरा भी साँस का माल नहीं — मास्क (पाठ-7)","1. गरम इंजन पर डीज़ल कभी न डालें: जनरेटर चलते-चलते बहुत गरम हो जाता है","तिरछी घिसाई में ग्राइंडर के फिसलने का ढंग सीधी घिसाई से अलग होता है","कान में दर्द, भारीपन, या सीटी बजना — तीनों चेतावनियाँ हैं, टालिए मत"),
  ("तेज़-दोहराव: पाठ-59 («तांबा पीतल का») का एक सूत्र?","तांबा लाल — पीतल पीला","रास्ता हमेशा साफ़ रखें","काम ख़त्म = वाल्व बंद","रखते समय भी घुटनों से"),
]
L[60]=[
  ("पाठ-60 («धातु पहचानने के देसी») का सार क्या है?","चिंगारी-जाँच वेल्डर की कसौटी है — ग्राइंडर की हल्की छुअन पर माइल्ड स्टील पीली फुलझड़ी छोड़ता है","चाप की गरमी की पहुँच सीमित है — मोटा लोहा सीधा जोड़ने पर ऊपर-ऊपर चिपकता है, भीतर कोरा रहता है","बिजली हमेशा आसान रास्ता खोजती है, और गीला शरीर उसका सबसे आसान रास्ता है — पसीना भी पानी ही है","आड़ी स्थिति पहली चढ़ाई है — टाँका दीवार पर, तालाब ढालू छत पर, और गुरुत्व पहली बार सामने से"),
  ("«धातु पहचानने के देसी» (पाठ-60) की आम ग़लती क्या है?","रंगी-चढ़ी सतह पर ऊपर-ऊपर जाँच — रंग के नीचे की धातु बोलती है, कोने पर ज़रा छीलकर परखिए","हर चमकती धातु को स्टेनलेस और हर मटमैली को माइल्ड स्टील मान लेना — जाँच के बिना नाम नहीं","पहले ही दिन लंबी लकीर का लोभ — छोटे टुकड़ों की सीधी माला लंबी घसीट से हज़ार गुना बेहतर","हर पुरानी चीज़ को \"बन जाएगा\" कह देना — काग़ज़ हो चुकी धातु पर वादा आपका नाम खा जाता है"),
  ("कौन-सी ग़लती «देसी तरीक़े चिंगारी जाँच» वाले पाठ-60 में बताई गई?","जाँच के जोश में ग्राहक की चीज़ के बीचों-बीच घाव बना देना — जाँच कोने की चीज़ है, चेहरे की नहीं","टैक के बाद गुनिया छोड़ देना — टैक की गरमी भी खड़े को खींचती है; तीन-बार-गुनिया का नियम बिना छूट","काले चश्मे में चिपिंग करना: वेल्डिंग हेलमेट या काले चश्मे को पहनकर चिपिंग करने की कोशिश न करें","झिरी ज़रूरत से बड़ी कर देना — बड़ा फ़ासला पतले माल में सीधे नीचे टपकता है (छेद-कथा पाठ-100 की)"),
  ("«धातु पहचानने के» (पाठ-60) की सावधानी क्या है?","चिंगारी-जाँच है तो ग्राइंडर-काम ही — चश्मा-दस्ताने-गार्ड बिना छूट के (पाठ-28)","स्टील-फ़ीते को कभी भी वेल्डिंग की सीधी चिंगारी या गरम लोहे के संपर्क में न लाएँ","त्वचा पर किरण की जलन हो जाए (लाल, तपती त्वचा) तो ठंडे साफ़ पानी से आराम दीजिए","मशीन के भीतर झाँकने की कोशिश भी केवल तभी करें जब प्लग पूरी तरह से बाहर निकला हो"),
  ("तेज़-दोहराव: पाठ-60 («धातु पहचानने के») का एक सूत्र?","ग्राइंडर = कसौटी","नीचे पटरा-तकिया","थकी बाँह = रुको","बुख़ार = डॉक्टर"),
]
L[61]=[
  ("पाठ-61 («कौन सी छड़ किस») का सार क्या है?","धातु और वेल्डिंग छड़ की सही जोड़ी बनाना वेल्डिंग की सबसे बुनियादी जरूरत है","सीधी लकीर वेल्डर की वर्णमाला का पहला अक्षर है, और उसकी कॉपी की लाइन चॉक-रेखा","घटिया या नक़ली लोहा कारीगर की साख और ग्राहक की जान दोनों के लिए ख़तरनाक है","जीआई (GI) यानी जस्ता चढ़ी चादर लोहे को ज़ंग से बचाने के लिए बहुत बढ़िया है"),
  ("«कौन सी छड़ किस» (पाठ-61) की आम ग़लती क्या है?","\"छड़ तो सिर्फ लोहा पिघलाती है\" सोचना: यही सबसे बड़ी भूल है","तौल-मिलान कभी न करना — कच्ची तौल चुपचाप महीनों खाती रहती है","आँख से मोटाई का दावा — रंगी-चढ़ी चादर आँख को मोटी दिखती है","खुले-बरसाती काम में एक-किनारा सिलाई — साल भर बाद फूला जोड़"),
  ("कौन-सी ग़लती «धातु पर जोड़ी तालिका» वाले पाठ-61 में बताई गई?","डिब्बे की लिखावट न पढ़ना: सिर्फ दुकानदार के भरोसे रहना और खुद डिब्बे पर लिखे निर्देश न पढ़ना आपको बड़ी मुसीबत में डाल सकता है","\"रंग तो ग्राहक कराएगा\" कहकर नंगा लोहा सौंपना: कुछ वेल्डर काम पूरा करके बिना रंग या प्राइमर (Primer) लगाए ही ढाँचा ग्राहक को दे","काम के बीच में बची हुई आधी छड़ों को ज़मीन पर फेंक देना: ज़मीन पर पड़ी छड़ें बहुत जल्दी मिट्टी और पानी सोख लेती हैं और बाद में","भारी काम में पतला एंगल लगा देना: शेड या भारी गेट पर बिना सोचे-समझे पतला एंगल लगा देने से वह कुछ ही दिनों में टेढ़ा हो जाता है"),
  ("«कौन सी छड़» (पाठ-61) की सावधानी क्या है?","खास छड़ें (जैसे SS और निकल) बहुत महँगी आती हैं","कल से हमारा काम सीधे हाथ का होने वाला है","लोहे का माल बहुत भारी और नुकीला होता है","दिन का पहला काम — तार पर एक नज़र"),
  ("तेज़-दोहराव: पाठ-61 («कौन सी छड़») का एक सूत्र?","MS = 6013 (रोज़ का काम) या 7018 (भारी काम)","रोशनी काम पर, आँख पर नहीं — चौंध अलग दुश्मन","खुरपी, रेगमाल और ग्राइंडर का इस्तेमाल करें","हर टुकड़ा गरम मानो — उठाना सिर्फ़ चिमटे से"),
]
L[62]=[
  ("पाठ-62 («गरमी और धातु फैलना») का सार क्या है?","धातु गरम होकर फैलती और ठंडी होकर सिकुड़ती है — और सिकुड़ता हुआ टाँका पूरे काम को अपनी ओर खींचकर टेढ़ा कर देता है","इस पाठ में हमने सीखा कि वेल्डिंग मशीन का करंट (एम्पीयर) असल में बिजली की आँच है, जिसे सही सेट करना बेहद ज़रूरी है","एल्युमिनियम अपनी हल्की और मज़बूत बनावट के कारण बहुत लोकप्रिय है, लेकिन वेल्डिंग के मामले में यह बेहद नखरेबाज़ है","इस पाठ में हमने बिजली के दो स्वभावों — AC (अल्टरनेटिंग करंट) और DC (डायरेक्ट करंट) को बहुत ही सरल तरीक़े से समझा"),
  ("«गरमी और धातु फैलना» (पाठ-62) की आम ग़लती क्या है?","टेढ़ी चीज़ को हथौड़े से पीटकर \"सीधा\" करना — कारण समझे बिना पीटना अगली बार वही रोग लाता है","सुर याद किए बिना सिर्फ़ नाम रटना — सुर कान से बैठता है, कॉपी से नहीं; असली चाप ज़रूर सुनिए","पतले लोहे पर बहुत मोटी छड़ चलाना: इससे लोहा तुरंत कटकर बह जाता है और काम ख़राब हो जाता है","एक ही पर्ची थमाना — विकल्प के बिना ग्राहक फ़ैसले का साथी नहीं, सिर्फ़ भुगतानकर्ता रहता है"),
  ("कौन-सी ग़लती «फैलना सिकुड़ना टेढ़ा होना» वाले पाठ-62 में बताई गई?","जाँच सिर्फ़ काम के अंत में करना — तब सुधार का दाम दस गुना हो चुका होता है","चिपकने पर ज़ोर-आज़माइश — कल का पाठ आने से पहले घबराइए मत, मशीन बंद कीजिए","कोण को चाँदा-नाप से रटने की ज़िद — नाप समझ के लिए है, हाथ आदत से सधता है","\"धातु ही तो है\" कहकर आम छड़ से हाथ डाल देना — हैंडल वाली कहानी याद रखिए"),
  ("«गरमी और धातु» (पाठ-62) की सावधानी क्या है?","तपे काम पर पानी डालना जोड़ के भीतर छिपा तनाव भरता है — यह टेढ़ेपन से भी बुरा सौदा है, क्योंकि दरार बिना बताए आती है","चादरों को क्लैंप से दबाते समय उँगलियाँ जबड़े की सीध से बाहर (पाठ-24), और पतले माल की सिलाई में पाठ-71 का पूरा क़ायदा","तप्त टुकड़े का ख़तरा: कटाई पूरी होने के बाद जो टुकड़ा कटकर अलग गिरता है, वह बहुत देर तक अत्यधिक तप्त (Hot) रहता है","पैने किनारे: जब भी कास्ट आयरन का कोई टूटा पुर्ज़ा आपके पास आए, तो उसके किनारे बहुत पैने और काँच जैसे तीखे होते हैं"),
  ("तेज़-दोहराव: पाठ-62 («गरमी और धातु») का एक सूत्र?","गरमी फैलाए, ठंडक सिकोड़े","बाद में जिंक पेंट की पोंछ","सिलेंडर सम्मान माँगता है","इन्वर्टर मशीन = DC बिजली"),
]
L[63]=[
  ("पाठ-63 («धातु की तैयारी सफ़ाई») का सार क्या है?","अच्छा जोड़ टाँके से पहले बनता है","चाप की बोली वेल्डर की तीसरी आँख है","वेल्डिंग मशीनों के दो परिवार हैं","पाइप आधुनिक वेल्डिंग की जान हैं"),
  ("«धातु की तैयारी सफ़ाई» (पाठ-63) की आम ग़लती क्या है?","\"चाप सब जला देगा\" वाला भरोसा — चाप जलाता ज़रूर है, पर जला हुआ कचरा जोड़ के भीतर ही क़ैद होता है","काले चश्मे में चिपिंग करना: वेल्डिंग हेलमेट या काले चश्मे को पहनकर चिपिंग करने की कोशिश न करें","झिरी ज़रूरत से बड़ी कर देना — बड़ा फ़ासला पतले माल में सीधे नीचे टपकता है (छेद-कथा पाठ-100 की)","टाँका चढ़ाई के बीचों-बीच ऊपर की सतह पर चला देना — सिलाई किनारे की रेखा पर होती है, पीठ पर नहीं"),
  ("कौन-सी ग़लती «तैयारी सफ़ाई रेती ग्राइंडर» वाले पाठ-63 में बताई गई?","रेती को आरी की तरह आगे-पीछे घसीटना — दाँत भी घिसे, सतह भी बिगड़े","थके हाथ से \"बस यह जोड़ और\" — इस दिशा में थकान की क़ीमत सबसे महँगी","माल आगे भागने पर चाल धीमी कर देना — उलटी दवा: यहाँ तेज़ी ही इलाज","टाँका ग़ौर से देखने के लिए धारा के ठीक ऊपर झुकना — सबसे आम ग़लती"),
  ("«धातु की तैयारी» (पाठ-63) की सावधानी क्या है?","घिसाई-खुरचाई का हर काम चश्मा-मास्क-दस्ताने माँगता है (हिस्सा-1 का पूरा कुनबा) — उड़ता ज़ंग-चूरा आँख और साँस दोनों का दुश्मन है","अर्थिंग पहरेदार है, छूट नहीं — अर्थिंग जुड़ी होने पर भी पाठ-6 के तीनों नियम (सूखा हाथ, सूखी ज़मीन, साबुत तार) पूरे पहरे पर रहेंगे","काम घुमाना-लिटाना ख़ुद एक काम है — भारी ढाँचा दो जन से, घोड़ियाँ-सहारे पहले जमाकर, उँगलियाँ किनारों की सीध से बाहर (पाठ-13/24)","प्लग बाहर निकालना: जब भी ग्राइंडर का पहिया बदलना हो या कोई मरम्मत करनी हो, तो सबसे पहले प्लग को बिजली के बोर्ड से बाहर खींचें"),
  ("तेज़-दोहराव: पाठ-63 («धातु की तैयारी») का एक सूत्र?","पाँच दुश्मन: ज़ंग-तेल-रंग-मैल-नमी — एक भी बचा तो टाँका भीतर से खोखला","पुराना बिना एवीआर वाला जनरेटर हो तो केवल भारी ट्रांसफार्मर मशीन चलाएं","पुरानी मशीन को कम से कम 5 मिनट चलाकर आवाज़, गंध और गरमी की जाँच करें","वारंटी के दौरान ढक्कन खोलने से सील टूटती है और वारंटी ख़त्म होती है"),
]
L[64]=[
  ("पाठ-64 («किनारे की तैयारी V») का सार क्या है?","चाप की गरमी की पहुँच सीमित है — मोटा लोहा सीधा जोड़ने पर ऊपर-ऊपर चिपकता है, भीतर कोरा रहता है","आड़ी स्थिति पहली चढ़ाई है — टाँका दीवार पर, तालाब ढालू छत पर, और गुरुत्व पहली बार सामने से","दुकान में बचे-कटे टुकड़ों को कबाड़ समझना एक आम कारीगर की भूल है, जबकि वे दबी हुई कमाई हैं","गैस वेल्डिंग में लौ को पहचानना और उसे नियंत्रित करना ही एक कुशल कारीगर की असली पहचान है"),
  ("«किनारे की तैयारी V» (पाठ-64) की आम ग़लती क्या है?","नाली इतनी खड़ी-सँकरी बनाना कि छड़ की नोक भीतर पहुँचे ही नहीं — घाटी खुले मुँह की चाहिए","हर चमकती धातु को स्टेनलेस और हर मटमैली को माइल्ड स्टील मान लेना — जाँच के बिना नाम नहीं","पहले ही दिन लंबी लकीर का लोभ — छोटे टुकड़ों की सीधी माला लंबी घसीट से हज़ार गुना बेहतर","हर पुरानी चीज़ को \"बन जाएगा\" कह देना — काग़ज़ हो चुकी धातु पर वादा आपका नाम खा जाता है"),
  ("कौन-सी ग़लती «नाली क्यों बनती है» वाले पाठ-64 में बताई गई?","पतली चादर पर उत्साह में नाली — वहाँ यह इलाज नहीं, नया रोग है","ज़ंग पर रंग फेरकर \"नया जैसा\" बेचना — वह मरम्मत नहीं, छलावा है","\"बाद में समेट लूँगा।\" — बाद कभी नहीं आता; अगला काम आ जाता है","बिना छीले वेल्डिंग करना — इससे न केवल ज़हरीला धुआँ निकलता है"),
  ("«किनारे की तैयारी» (पाठ-64) की सावधानी क्या है?","तिरछी घिसाई में ग्राइंडर के फिसलने का ढंग सीधी घिसाई से अलग होता है","तांबे-पीतल की घिसाई का महीन चूरा भी साँस का माल नहीं — मास्क (पाठ-7)","कान में दर्द, भारीपन, या सीटी बजना — तीनों चेतावनियाँ हैं, टालिए मत","खड़ी टिकाई गई चादरें और भारी पाइप गिरने पर जानलेवा चोट दे सकते हैं"),
  ("तेज़-दोहराव: पाठ-64 («किनारे की तैयारी») का एक सूत्र?","मोटे में चाप की पहुँच छोटी","बाद में जिंक पेंट की पोंछ","गुनिया-विकर्ण बीच-बीच में","पाँच मिनट, हर दिन, हर हाल"),
]
L[65]=[
  ("पाठ-65 («पुराने जंग लगे लोहे») का सार क्या है?","पुराना लोहा बूढ़ा मरीज़ है — पहले ठक-ठक और खुरचन से नाड़ी देखो: ऊपर की मैल है या भीतर तक खाया घुन","दुर्घटना का आधा हिस्सा मशीन से नहीं, बिखरी जगह से आता है — इसलिए वेल्डर की दुकान रसोई की तरह सजती है","लोहे की मज़बूती केवल उसकी मोटाई पर निर्भर नहीं करती, बल्कि उसके आकार और सही बनावट पर टिकी होती है","इस पाठ में हमने पिछले तीस पाठों (पाठ 51 से 79) के धातु-ज्ञान का पूरा निचोड़ पाँच गिरहों में समझा"),
  ("«पुराने जंग लगे लोहे» (पाठ-65) की आम ग़लती क्या है?","मैल-ज़ंग के ऊपर टाँका — चमक हफ़्ते की, उखड़ना पक्का","कतरन को कचरा समझना: इसके टुकड़े बहुत क़ीमती होते हैं","ऊँच-नीच किनारों पर सीधी सिलाई — ऊँचा जला, नीचा कोरा","फ़ीते के हुक को हथौड़ी से ठोकना: यह सबसे आम गलती है"),
  ("कौन-सी ग़लती «लगे लोहे पर काम» वाले पाठ-65 में बताई गई?","हर पुरानी चीज़ को \"बन जाएगा\" कह देना — काग़ज़ हो चुकी धातु पर वादा आपका नाम खा जाता है","हर चमकती धातु को स्टेनलेस और हर मटमैली को माइल्ड स्टील मान लेना — जाँच के बिना नाम नहीं","पहले ही दिन लंबी लकीर का लोभ — छोटे टुकड़ों की सीधी माला लंबी घसीट से हज़ार गुना बेहतर","कोनों को बिना सहारे के छोड़ना: भारी लोड वाले ढाँचों में ब्रेस न लगाना सबसे बड़ी भूल है"),
  ("«पुराने जंग लगे» (पाठ-65) की सावधानी क्या है?","सबसे बड़ी बात दोबारा — बंद पाइप-टंकी पर बिना खोले चाप कभी नहीं","धारदार औज़ारों की नोक ढककर रखें: जब भी आप पेटी में हाथ डालें","करंट की घुंडी प्लास्टिक की बनी होती है ताकि आपको करंट न लगे","गरम पपड़ी का ख़तरा: उतरी हुई पपड़ी बहुत देर तक गरम रहती है"),
  ("तेज़-दोहराव: पाठ-65 («पुराने जंग लगे») का एक सूत्र?","ठक-ठक = नाड़ी: खनक ठोस, बुझी खोखली","धारदार औज़ारों की नोक हमेशा ढकी रहे","केबल की कुंडली = हमेशा ढीली और गोल","हर नई चीज़ का पहला अभ्यास समतल में"),
]
L[66]=[
  ("पाठ-66 («रंगे पेंटेड लोहे पर») का सार क्या है?","रंगे लोहे पर वेल्डिंग करना जोड़ और सेहत दोनों के लिए ख़तरनाक है","ज़ंग लोहे का एक ऐसा रोग है जो नमी और हवा के मिलने से पैदा होता है","ओवरहेड सीढ़ी की चोटी है — गुरुत्व पूरा दुश्मन, हर बूँद आपकी ओर","अट्ठाईस पाठों की धातु-विद्या तीन सवालों की छलनी में सिमटती है"),
  ("«रंगे पेंटेड लोहे पर» (पाठ-66) की आम ग़लती क्या है?","\"पेंट बहुत पतला है, जलकर साफ़ हो जाएगा\" सोचना: यह सबसे बड़ी भूल है","\"गरमी बहुत है, बनियान में कर लेता हूँ।\" — किरण को मौसम से मतलब नहीं","मिली-जुली बोरी बेचना: बिना छँटाई किए कबाड़ बेचना सबसे बड़ा घाटा है","सिलेंडर को लुढ़काकर लाना — वाल्व की गर्दन हर लुढ़कन में दाँव पर है"),
  ("कौन-सी ग़लती «पेंटेड लोहे पर काम» वाले पाठ-66 में बताई गई?","काम के बाद नंगे लोहे को ऐसे ही छोड़ देना: बिना ज़ंग-रोधी पेंट के वह जगह कुछ ही दिनों में ज़ंग खाकर कमज़ोर हो जाएगी","पूरी खेप को एक-सा मान लेना — डीलर अक्सर ऊपर की दो डंडियाँ असली ब्रांड की रखते हैं और नीचे घटिया माल छुपा देते हैं","गलत पोलैरिटी (Polarity) चुनना: अगर डीसी (DC) वेल्डिंग करते समय आपने टॉर्च को प्लस (+) वाले टर्मिनल में जोड़ दिया","ख़राबी मिलने पर \"चला लेंगे\" — जाँच का पूरा मतलब ही तब है जब ख़राबी पर काम रुके; वरना जाँच रस्म है, सुरक्षा नहीं"),
  ("«रंगे पेंटेड लोहे» (पाठ-66) की सावधानी क्या है?","पेंट छीलने का काम हमेशा खुली हवा में या पंखे के सामने करें ताकि धूल और धुआँ आपसे दूर उड़े","अभ्यास-ठिये पर हिस्सा-1 के पूरे नियम — पानी-बाल्टी पास, घेरा साफ़, हवादार जगह (पाठ-5/8/16)","अगले हिस्से (यंत्रों की पहचान) में हम मशीन के और पास जाएँगे — पुर्ज़े, बटन, छड़ें, सेटिंग","बैटरी मरी तो काम बंद: हमेशा ध्यान रखें कि अगर आपके हेलमेट की बैटरी कमज़ोर या ख़राब हो गई है"),
  ("तेज़-दोहराव: पाठ-66 («रंगे पेंटेड लोहे») का एक सूत्र?","रंग = जोड़ का कचरा + साँस का ज़हर","केबल की कुंडली = हमेशा ढीली और गोल","तांबे की कतरन क़ीमती — ठिकाना अलग","नाप = बाहरी आकार + दीवार की मोटाई"),
]
L[67]=[
  ("पाठ-67 («बाज़ार से लोहा ख़रीदना») का सार क्या है?","लोहा ख़रीदना वेल्डिंग के धंधे का सबसे महत्वपूर्ण हिस्सा है","नीचे से ऊपर की चढ़ाई ज़िम्मेदार खड़े जोड़ों की शाही सड़क है","तांबा और पीतल लोहे के कुनबे से बाहर के दो रंगीन पड़ोसी हैं","ग्राइंडर वेल्डर का सबसे उपयोगी लेकिन सबसे ख़तरनाक औज़ार है"),
  ("«बाज़ार से लोहा ख़रीदना» (पाठ-67) की आम ग़लती क्या है?","उधार के लालच में घटिया माल लेना: कई बार कारीगर उधार खाता चलाने के चक्कर में दुकानदार का हर तरह का टेढ़ा और जंग लगा माल चुपचाप ले","दस्ताने वाले हाथ से पपड़ी झाड़ना: कई वेल्डर चिपिंग हथौड़ा मारने के बाद बची हुई धूल को अपने दस्ताने वाले हाथ से ही पोंछ देते हैं","नियमों को सिर्फ़ काग़ज़ पर रखना: दीवार पर चार्ट टाँग दिया पर होल्डर अभी भी ढीला ही इस्तेमाल कर रहे हैं — यह खुद को धोखा देना है","4. सुरक्षा उपकरणों को नज़रअंदाज़ करना: बिना व्हील-गार्ड का ग्राइंडर या बिना अर्थिंग वाला प्लग यह सोचकर ले लेना कि 'एक ही दिन की"),
  ("कौन-सी ग़लती «नाप भाव मोल भाव» वाले पाठ-67 में बताई गई?","बिना पुर्ज़ी के माल उठाना: बिना लिखे वज़न और भाव के माल कभी न लें, बाद में हिसाब में गड़बड़ होना तय है","अच्छे अंक पर माला छोड़ देना — ज्ञान का इम्तिहान आज हुआ; आदत का इम्तिहान बिजली, आग और थकान रोज़ लेते हैं","पतले सर्विस वायर (Service Wire) का उपयोग: लोड के हिसाब से तार पतला होने पर बिजली का बिल तो बढ़ता ही है","घुमाने का आलस — \"लिटाने में वक़्त लगेगा\" कहकर खड़े से लड़ना: लिटाने का वक़्त हमेशा झालर छीलने से सस्ता"),
  ("«बाज़ार से लोहा» (पाठ-67) की सावधानी क्या है?","लोहे का माल बहुत भारी और नुकीला होता है","कल से हमारा काम सीधे हाथ का होने वाला है","खास छड़ें (जैसे SS और निकल) बहुत महँगी आती हैं","भार के दावे में हमेशा अपनी ज़बान नपी-तुली रखें"),
  ("तेज़-दोहराव: पाठ-67 («बाज़ार से लोहा») का एक सूत्र?","लोहा नाप से माँगो = क़िस्म + नाप + मोटाई","कम = ऊँचा-चढ़ा, अनमिले किनारे, चिपकती छड़","चाल का संतुलन = न बहुत तेज़, न बहुत धीमे","भड़भड़-फुसकार = ज़्यादा करंट/लंबा फ़ासला"),
]
L[68]=[
  ("पाठ-68 («लोहे के रूप पत्ती») का सार क्या है?","इस पाठ में हमने लोहे यानी माइल्ड स्टील के पाँच मुख्य रूपों — पत्ती, पाइप, एंगल, चादर और सरिये की पहचान की","बिजली गोल घेरे में चलती है — मशीन से होल्डर-छड़ के रास्ते काम तक, और काम से अर्थ-क्लैंप के रास्ते वापस","गैस वेल्डिंग में रेगुलेटर और उसके दोनों गेज हमारी सुरक्षा और काम की सफ़ाई के लिए सबसे ज़रूरी औज़ार हैं","इस पाठ में हमने सीखा कि एक पेशेवर वेल्डर की असली पहचान उसकी व्यवस्थित औज़ार-पेटी (Toolbox) से होती है"),
  ("«लोहे के रूप पत्ती» (पाठ-68) की आम ग़लती क्या है?","इलाक़ाई नामों की खिचड़ी बनाना: कई जगह पत्ती को \"पटरा\" और एंगल को \"कोनिया\" कहा जाता है","पहले ही दिन लंबी लकीर का लोभ — छोटे टुकड़ों की सीधी माला लंबी घसीट से हज़ार गुना बेहतर","चालू मशीन में होल्डर यूँ ही फेंक देना — जहाँ छुएगा, वहीं चिंगारी; ठिकाना = सूखी खूँटी","उतरते-उतरते लाइन लंबी खींचते जाना — टुकड़ों-साँस का नियम (पाठ-94) खड़ी में भी उतना ही"),
  ("कौन-सी ग़लती «पाइप एंगल चादर सरिया» वाले पाठ-68 में बताई गई?","चादर और पत्ती में भ्रम: कई बार लोग पतली पत्ती की जगह चादर को काटकर पट्टी बनाने की कोशिश करते हैं","टाँका बिगड़ते ही मशीन खोलना/मिस्त्री दौड़ना — पहले चालीस सेकंड की क्लैंप-जाँच; आधी बीमारी वहीं है","थकी बाँह से \"बस यह टुकड़ा और\" — काँपते हाथ का आख़िरी टुकड़ा ही अक्सर पूरी लकीर की बदनामी बनता है","टैक के बाद गुनिया छोड़ देना — टैक की गरमी भी खड़े को खींचती है; तीन-बार-गुनिया का नियम बिना छूट"),
  ("«लोहे के रूप» (पाठ-68) की सावधानी क्या है?","लोहे के इन रूपों के साथ काम करते समय सुरक्षा सबसे पहले है","गरम पपड़ी का ख़तरा: उतरी हुई पपड़ी बहुत देर तक गरम रहती है","पहला इलाज इलाज की जगह नहीं लेता — वह डॉक्टर तक का पुल है","चादर का पूरा बदन धार है — उठाना-पलटना दस्ताने से (पाठ-4)"),
  ("तेज़-दोहराव: पाठ-68 («लोहे के रूप») का एक सूत्र?","पाँच रूप = पत्ती, चादर, पाइप, एंगल, सरिया","चाल का संतुलन = न बहुत तेज़, न बहुत धीमे","भड़भड़-फुसकार = ज़्यादा करंट/लंबा फ़ासला","कान-रक्षक पहनकर ही सुनो — उतारो कभी नहीं"),
]
L[69]=[
  ("पाठ-69 («एंगल और चैनल ढाँचे») का सार क्या है?","एंगल और चैनल वेल्डिंग के काम की असली रीढ़ हैं","थकान भीतर का दुश्मन है — वह ख़ुद चोट नहीं देती","वेल्डिंग का आर्क हाथ के पास जलता छोटा सूरज है","चादर वेल्डर की मलमल है — ग़लती माफ़ नहीं करती"),
  ("«एंगल और चैनल ढाँचे» (पाठ-69) की आम ग़लती क्या है?","नाप बताते समय मोटाई भूल जाना: अक्सर नए कारीगर सिर्फ़ \"25×25 का एंगल दे दो\" कहकर रुक जाते हैं","गलत जगह गलत पाइप चुनना: सीढ़ी की पकड़-पट्टी में चौकोर पाइप लगा देना, जिससे हाथ में कोने चुभें","चाल-कोण उल्टी दिशा में झुकाना — छड़ आगे की ओर लेटे तो तालाब आगे भागकर आर्क के नीचे आ जाता है","सारे औज़ारों को एक ही बोरे में भर देना: बोरा पेटी नहीं है! बोरे में औज़ार आपस में टकराते हैं"),
  ("कौन-सी ग़लती «चैनल ढाँचे की हड्डियाँ» वाले पाठ-69 में बताई गई?","भारी काम में पतला एंगल लगा देना: शेड या भारी गेट पर बिना सोचे-समझे पतला एंगल लगा देने से वह कुछ ही दिनों में टेढ़ा हो जाता है","\"रंग तो ग्राहक कराएगा\" कहकर नंगा लोहा सौंपना: कुछ वेल्डर काम पूरा करके बिना रंग या प्राइमर (Primer) लगाए ही ढाँचा ग्राहक को दे","काम के बीच में बची हुई आधी छड़ों को ज़मीन पर फेंक देना: ज़मीन पर पड़ी छड़ें बहुत जल्दी मिट्टी और पानी सोख लेती हैं और बाद में","चश्मा और कान-रक्षक न पहनना: ग्राइंडर की तेज़ चीख़ आपके कानों को बहरा कर सकती है (जैसा पाठ-12 में पढ़ा था) और उड़ती चिंगारियाँ"),
  ("«एंगल और चैनल» (पाठ-69) की सावधानी क्या है?","पैनी धार से बचना: जब हम एंगल या चैनल को काटते हैं, तो उसके कटे हुए सिरे सुई की तरह पैने हो जाते हैं","स्टेनलेस स्टील को काटने या घिसने के लिए हमेशा उसका अपना अलग ग्राइंडिंग व्हील (Grinding Wheel) रखें","उँगलियों को बचाएँ: जब वायर-फीडर के पहिए घूम रहे हों, तो उसके भीतर कभी भी उँगली या पेचकस न डालें","तेल/पेट्रोल/डीज़ल रही टंकी — विशेषज्ञ-जाँच और पूरी सफ़ाई-प्रमाण के बिना उस पर टाँका बिलकुल नहीं"),
  ("तेज़-दोहराव: पाठ-69 («एंगल और चैनल») का एक सूत्र?","नाप का नियम: पंख × पंख × मोटाई","स्क्राइबर = बारीक और सटीक खरोंच","जोड़ से रंग-ज़ंग-तेल पहले साफ़","पूरी बाँह + पूरा पैंट, हर मौसम"),
]
L[70]=[
  ("पाठ-70 («पाइप गोल और चौकोर») का सार क्या है?","पाइप आधुनिक वेल्डिंग की जान हैं","वेल्डिंग मशीनों के दो परिवार हैं","अच्छा जोड़ टाँके से पहले बनता है","चाप की बोली वेल्डर की तीसरी आँख है"),
  ("«पाइप गोल और चौकोर» (पाठ-70) की आम ग़लती क्या है?","दीवार की मोटाई पूछे बिना दाम की तुलना: दो पाइप बाहर से एक जैसे दिख सकते हैं","\"टंकी को पानी से धो लिया, अब ठीक है।\" — एक बार धोने से भीतर की भाप नहीं मरती","मोटी पेंसिल या स्केच पेन का उपयोग: मोटी लकीर वेल्डिंग में भ्रम पैदा करती है","नाक से सूँघकर रिसाव ढूँढना: कई लोग सोचते हैं कि गैस लीक होगी तो महक आ जाएगी"),
  ("कौन-सी ग़लती «पाइप गोल और चौकोर» वाले पाठ-70 में बताई गई?","ढाँचे के पाइप को पानी की लाइन में लगाना: ग्रिल वाले पाइप में पानी का दबाव झेलने की ताक़त नहीं होती, वह जल्दी लीक हो जाएगा","गलत चाल से चलना: बहुत धीमी चाल से चलने पर कट बहुत चौड़ा और ख़राब बनता है, और बहुत तेज़ चलने पर कट बीच में ही टूट जाता है","गलती 3 — तेल-पानी की जाँच न करना: जनरेटर चलाने से पहले उसका मोबिल ऑयल (Mobil Oil) और रेडिएटर (Radiator) का पानी न जाँचना","पहिया-रक्षक (Guard) को उतारकर फेंकना: यह सोचना कि \"रक्षक के बिना काम जल्दी होता है\" आपकी सबसे बड़ी भूल साबित हो सकती है"),
  ("«पाइप गोल और» (पाठ-70) की सावधानी क्या है?","भीतर की हवा का रास्ता खुला रखें: पाइप भीतर से एक खोखली सुरंग है","आर्क आई हो जाए तो आँख मलिए मत — झुलसी झिल्ली मलने से और छिलती है","उतरती लकीर में तपा माल और छींटे आपके हाथ के नीचे की ओर बहते हैं","सबसे बड़ी बात दोबारा — बंद पाइप-टंकी पर बिना खोले चाप कभी नहीं"),
  ("तेज़-दोहराव: पाठ-70 («पाइप गोल और») का एक सूत्र?","नाप = बाहरी आकार + दीवार की मोटाई","केबल की कुंडली = हमेशा ढीली और गोल","तांबे की कतरन क़ीमती — ठिकाना अलग","चप्पल पर वेल्डिंग = पैर पर अंगारा"),
]
L[71]=[
  ("पाठ-71 («चादर के काम पतले») का सार क्या है?","चादर वेल्डर की मलमल है — ग़लती माफ़ नहीं करती","थकान भीतर का दुश्मन है — वह ख़ुद चोट नहीं देती","वेल्डिंग का आर्क हाथ के पास जलता छोटा सूरज है","एंगल और चैनल वेल्डिंग के काम की असली रीढ़ हैं"),
  ("«चादर के काम पतले» (पाठ-71) की आम ग़लती क्या है?","मोटे वाले भरोसे से पतले पर उतरना — \"टाँका तो टाँका है\" इस काम की सबसे महँगी कहावत है","\"आग लगी तो देख लेंगे।\" — बिना पास रखी बाल्टी के \"देख लेना\" सिर्फ़ जलता हुआ देखना है","काम के हिसाब से गलत मशीन चुनना: बिना सोचे-समझे बहुत भारी या बहुत हल्की मशीन ले लेना","पहले ही दिन लकीर-टाँके की होड़ — सीढ़ी का पहला डंडा छोड़ने वाला मुँह के बल गिरता है"),
  ("कौन-सी ग़लती «काम पतले की चुनौती» वाले पाठ-71 में बताई गई?","छेद होते ही उसी गरम पल में भरने की जल्दबाज़ी — गरम किनारे और गलते हैं (भराई की पूरी रीत पाठ-100 में)","चालू मशीन में सफ़ाई या कसाव करना: कुछ लोग मशीन का स्विच ऑन रखते हुए ही पेचकश से टर्मिनल कसने लगते हैं","लोहा पूरा लाल होने से पहले लीवर दबाना: कई नए कारीगर लोहा पूरा गर्म होने से पहले ही लीवर दबा देते हैं","उमेठ+टेप का देसी जोड़ स्थायी बना लेना — सबसे गरम टोल-नाका; सही जोड़-पुर्ज़ा सस्ता है, जली केबल महँगी"),
  ("«चादर के काम» (पाठ-71) की सावधानी क्या है?","चादर का पूरा बदन धार है — उठाना-पलटना दस्ताने से (पाठ-4)","लोहे के इन रूपों के साथ काम करते समय सुरक्षा सबसे पहले है","पहला इलाज इलाज की जगह नहीं लेता — वह डॉक्टर तक का पुल है","गरम पपड़ी का ख़तरा: उतरी हुई पपड़ी बहुत देर तक गरम रहती है"),
  ("तेज़-दोहराव: पाठ-71 («चादर के काम») का एक सूत्र?","मोटा माफ़ करता है, पतला नहीं","चोट = पाठ-10, हर महीने दोहराव","सुरक्षा सामान हमेशा सबसे ऊपर","फ़ैसला माल करता है, जोश नहीं"),
]
L[72]=[
  ("पाठ-72 («सरिया के काम ग्रिल») का सार क्या है?","सरिया ग्रिल-दुनिया की जान है, पर दो जातियों में बँटा है","कोने का जोड़ हर चौकोर चीज़ के चारों सिरों की रीढ़ है","कारख़ाने की दीवारें चार रंगों की भाषा में बोलती हैं","एक बेहतरीन वेल्डर अपनी मशीन का खुद डॉक्टर होता है"),
  ("«सरिया के काम ग्रिल» (पाठ-72) की आम ग़लती क्या है?","ढलाई वाला पसलीदार सरिया ग्रिल में ठोकना — पसलियाँ न शोभा देतीं, न टाँके को साफ़ बैठने देतीं","नाप बताते समय मोटाई भूल जाना: अक्सर नए कारीगर सिर्फ़ \"25×25 का एंगल दे दो\" कहकर रुक जाते हैं","सिर्फ़ दाम देखकर सबसे सस्ती उठाना — अपनी बिजली, अपना काम देखे बिना ली मशीन सस्ती नहीं पड़ती","ऊँचे-चढ़े टाँके को \"मोटा है, मज़बूत होगा\" कहना — अनमिले किनारे वाला ढेर टिका है, जुड़ा नहीं"),
  ("कौन-सी ग़लती «काम ग्रिल की जान» वाले पाठ-72 में बताई गई?","मोटाई सिर्फ़ एक सिरे पर नापना — घटिया माल की चोरी बीच में छिपी होती है","\"धातु ही तो है\" कहकर आम छड़ से हाथ डाल देना — हैंडल वाली कहानी याद रखिए","नोक नीचे की ओर झुकाना — धक्का माल को और नीचे धकेलता है, दौड़ वहीं हारी","\"झनझनाहट हल्की है, चलता है।\" — हल्की झनझनाहट बड़ी रिसन की पहली बूँद है"),
  ("«सरिया के काम» (पाठ-72) की सावधानी क्या है?","सरिये का बँधा लच्छा-बंडल खोलते समय सिरे कमानी की तरह झटके से उछलते हैं — चेहरा हटाकर, दस्ताने पहनकर, बंधन आख़िर में काटिए","कान-रक्षा (पाठ-12) से समझौता कभी नहीं — और यह उल्टी समझ निकाल दीजिए कि \"सुनने के लिए रक्षक उतारना पड़ेगा\": अच्छा कान-रक्षक","घटिया निकला माल कभी भी ऐसे कामों में इस्तेमाल न करें जहाँ जान का जोखिम हो (जैसे झूला, सीढ़ी, छत की रेलिंग, या भारी छज्जा)","माइल्ड स्टील नरम है, पर उसकी कटी हुई धार और किनारे उतने ही तीखे हैं — दस्ताने का नियम (पाठ-4) धातु देखकर ढीला नहीं पड़ता"),
  ("तेज़-दोहराव: पाठ-72 («सरिया के काम») का एक सूत्र?","सादा = ग्रिल-जाली-सजावट","रास्ता हमेशा साफ़ रखें","तिकड़ी: करंट-चाल-झुकाव","घर: पतला माल-शोभा-होंठ"),
]
L[73]=[
  ("पाठ-73 («बचे कटे टुकड़ों की») का सार क्या है?","दुकान में बचे-कटे टुकड़ों को कबाड़ समझना एक आम कारीगर की भूल है, जबकि वे दबी हुई कमाई हैं","आड़ी स्थिति पहली चढ़ाई है — टाँका दीवार पर, तालाब ढालू छत पर, और गुरुत्व पहली बार सामने से","गैस वेल्डिंग में लौ को पहचानना और उसे नियंत्रित करना ही एक कुशल कारीगर की असली पहचान है","पायलट हज़ार उड़ानों के बाद भी सूची से जाँचता है, क्योंकि याददाश्त थकती है और सूची नहीं"),
  ("«बचे कटे टुकड़ों की» (पाठ-73) की आम ग़लती क्या है?","\"जगह घेरता है\" कहकर हर हफ़्ते सब फेंक देना: कुछ कारीगर रोज़-रोज़ की सफ़ाई के चक्कर में हर छोटे टुकड़े को नाली या कचरे में फेंक","दस्ताने वाले हाथ से पपड़ी झाड़ना: कई वेल्डर चिपिंग हथौड़ा मारने के बाद बची हुई धूल को अपने दस्ताने वाले हाथ से ही पोंछ देते हैं","\"रंग तो ग्राहक कराएगा\" कहकर नंगा लोहा सौंपना: कुछ वेल्डर काम पूरा करके बिना रंग या प्राइमर (Primer) लगाए ही ढाँचा ग्राहक को दे","टैक के बाद सीध-जाँच छोड़कर सीधी भराई — दो सेकंड की अदालत टालने वाला दो घंटे की सज़ा काटता है (पाठ-93 में यह कहानी पूरी मिलेगी)"),
  ("कौन-सी ग़लती «क़ीमत कबाड़ नहीं कमाई» वाले पाठ-73 में बताई गई?","मिली-जुली बोरी बेचना: बिना छँटाई किए कबाड़ बेचना सबसे बड़ा घाटा है","\"गरमी बहुत है, बनियान में कर लेता हूँ।\" — किरण को मौसम से मतलब नहीं","\"पेंट बहुत पतला है, जलकर साफ़ हो जाएगा\" सोचना: यह सबसे बड़ी भूल है","सिलेंडर को लुढ़काकर लाना — वाल्व की गर्दन हर लुढ़कन में दाँव पर है"),
  ("«बचे कटे टुकड़ों» (पाठ-73) की सावधानी क्या है?","कतरन का कोना कोई साधारण कोना नहीं है, वह नुकीले और धारदार टुकड़ों का एक छोटा जंगल है","अभ्यास की मस्ती में वर्दी ढीली नहीं — हिस्सा-1 की क़सम रोज़ की है, पहले दिन की नहीं","तेल और ग्रीस से कट्टर दुश्मनी: यह गैस वेल्डिंग का सबसे बड़ा और सबसे ख़तरनाक नियम है","किनारा-कटना ज़िम्मेदार जोड़ (झूला, रेलिंग, सीढ़ी, भार-ढाँचा) पर दिखे तो टालना नहीं"),
  ("तेज़-दोहराव: पाठ-73 («बचे कटे टुकड़ों») का एक सूत्र?","कतरन की तीन क़ीमतें: काम में दोबारा इस्तेमाल, कबाड़ में बेचान, और नए लड़कों का अभ्यास","औज़ार-सीढ़ी: चिकनाई पर पोंछ → हल्की मैल पर ब्रश → जमी परत पर ग्राइंडर → कोनों में रेती","हवा इसका सबसे बड़ा दुश्मन है, हवा चली तो गैस उड़ी और वेल्डिंग में छेद (Porosity) हुए","विकर्ण-जाँच (Diagonal Check) = तिरछे कोनों की नाप बराबर होना यानी ढाँचा एकदम सीधा होना"),
]
L[74]=[
  ("पाठ-74 («धातु का हिसाब वज़न») का सार क्या है?","लोहा तुलकर बिकता है पर नपकर आता है — दोनों भाषाओं का अनुवाद वज़न-पर्ची है","धातु और वेल्डिंग छड़ की सही जोड़ी बनाना वेल्डिंग की सबसे बुनियादी जरूरत है","इस पाठ में हमने हिस्सा-2 (यंत्र-ज्ञान) की पूरी यात्रा को एक जगह समेटा है","घटिया या नक़ली लोहा कारीगर की साख और ग्राहक की जान दोनों के लिए ख़तरनाक है"),
  ("«धातु का हिसाब वज़न» (पाठ-74) की आम ग़लती क्या है?","छपे अंक रटकर हमेशा के लिए मान लेना — तालिका-अंक नाप-दर-नाप बदलते हैं और भाव रोज़; पर्ची अपनी, भाव आज का","जोड़ाई छिपाने को उस पर मोटा ढेर चढ़ा देना — गाँठ ढँकती नहीं, बड़ी होती है; इलाज रीत में है, ढेर में नहीं","अच्छे अंक पर माला छोड़ देना — ज्ञान का इम्तिहान आज हुआ; आदत का इम्तिहान बिजली, आग और थकान रोज़ लेते हैं","पतले सर्विस वायर (Service Wire) का उपयोग: लोड के हिसाब से तार पतला होने पर बिजली का बिल तो बढ़ता ही है"),
  ("कौन-सी ग़लती «वज़न से दाम निकालना» वाले पाठ-74 में बताई गई?","तौल-मिलान कभी न करना — कच्ची तौल चुपचाप महीनों खाती रहती है","आँख से मोटाई का दावा — रंगी-चढ़ी चादर आँख को मोटी दिखती है","खुले-बरसाती काम में एक-किनारा सिलाई — साल भर बाद फूला जोड़","अंदाज़े से काम करना: \"मेरी आँख ही गुनिया है\" कहना बंद करें"),
  ("«धातु का हिसाब» (पाठ-74) की सावधानी क्या है?","वज़न-गणित औज़ार है, हथियार नहीं — दूसरे कारीगर का भेद ग्राहक के सामने खोलते समय ज़बान नपी रखिए: अपना हिसाब दिखाइए","तप्त टुकड़े का ख़तरा: कटाई पूरी होने के बाद जो टुकड़ा कटकर अलग गिरता है, वह बहुत देर तक अत्यधिक तप्त (Hot) रहता है","मीटर का लोड बढ़वाना हो, कनेक्शन की श्रेणी (घरेलू से व्यावसायिक) बदलवानी हो, या मीटर ख़राब होने की शिकायत करनी हो","पैने किनारे: जब भी कास्ट आयरन का कोई टूटा पुर्ज़ा आपके पास आए, तो उसके किनारे बहुत पैने और काँच जैसे तीखे होते हैं"),
  ("तेज़-दोहराव: पाठ-74 («धातु का हिसाब») का एक सूत्र?","दाम = किलो × भाव; किलो = नाप-मोटाई से","क्रम: सफ़ाई → दबाओ → टैक → सिलो → पलटो","\"आदत\" दिमाग़ को पड़ती है, कान को नहीं","साबुत ढँकाव (नंगा तांबा = नंगी बिजली)"),
]
L[75]=[
  ("पाठ-75 («धातु रखने का ढंग») का सार क्या है?","गोदाम का सलीक़ा वेल्डिंग दुकान की रीढ़ है","पहला आर्क अनुशासन की परीक्षा है, जोश की नहीं","रोशनी और हवा काम की जगह की दो साँसें हैं","टूटना-चिपकना नए का पहला संघर्ष है — हार नहीं"),
  ("«धातु रखने का ढंग» (पाठ-75) की आम ग़लती क्या है?","\"अभी रख दो, बाद में जमाएँगे\" सोचना: यही आदत गोदाम को कबाड़ख़ाना बना देती है","\"झटका छोटा था, ठीक हूँ\" — बिजली का हिसाब भीतर चलता है; जाँच हर झटके के बाद","तीन-लकीर अभ्यास को \"बच्चों का खेल\" समझकर छोड़ना — यही खेल आँख की डिग्री है","कान में रुई ठूँसना — रुई धूल की ढाल है, शोर की नहीं; ऊपर से झूठा भरोसा अलग"),
  ("कौन-सी ग़लती «ढंग गोदाम की समझ» वाले पाठ-75 में बताई गई?","नए माल को पुराने माल के ऊपर लाद देना: इससे पुराना माल नीचे दबा-दबा ज़ंग खा जाता है","\"आग लगी तो देख लेंगे।\" — बिना पास रखी बाल्टी के \"देख लेना\" सिर्फ़ जलता हुआ देखना है","शोभा के काम में खुला कोना छोड़ देना — बाहर की घाटी-लकीर ग्राहक की आँख में चुभती है","जले पर टूथपेस्ट/तेल/हल्दी/राख — ठंडक का धोखा, ज़ख़्म की गहराई और संक्रमण का न्योता"),
  ("«धातु रखने का» (पाठ-75) की सावधानी क्या है?","खड़ी टिकाई गई चादरें और भारी पाइप गिरने पर जानलेवा चोट दे सकते हैं","तिरछी घिसाई में ग्राइंडर के फिसलने का ढंग सीधी घिसाई से अलग होता है","कटी-छिली केबल दिखे तो नियम पाठ-6 वाला ही — पहले मशीन बंद, फिर इलाज","कान में दर्द, भारीपन, या सीटी बजना — तीनों चेतावनियाँ हैं, टालिए मत"),
  ("तेज़-दोहराव: पाठ-75 («धातु रखने का») का एक सूत्र?","लोहा ज़मीन से ऊपर हो","तांबा लाल — पीतल पीला","बूँद-बूँद, जगह बदलकर","तीन पहचान — कसी पकड़"),
]
L[76]=[
  ("पाठ-76 («मौसम और धातु बरसात») का सार क्या है?","वेल्डर का भी पंचांग होता है","पाइप आधुनिक वेल्डिंग की जान हैं","वेल्डिंग मशीनों के दो परिवार हैं","अच्छा जोड़ टाँके से पहले बनता है"),
  ("«मौसम और धातु बरसात» (पाठ-76) की आम ग़लती क्या है?","तिरपाल को कसकर लपेटना — क़ैद की भाप ख़ुद बरसात बन जाती है","आँख से मोटाई का दावा — रंगी-चढ़ी चादर आँख को मोटी दिखती है","कच्चा-ठंडा टैक — हिलाते ही खुले तो वह खूँटा नहीं, धोखा है","टुकड़े कसकर भिड़ाना — \"सटे = जुड़े\" वाली उल्टी सहज-बुद्धि"),
  ("कौन-सी ग़लती «बरसात गर्मी की मार» वाले पाठ-76 में बताई गई?","धूप के तपे माल पर सीधी नाप-टाँका — पाठ-29/62 की सीख भूलना","आँख से मोटाई का दावा — रंगी-चढ़ी चादर आँख को मोटी दिखती है","कच्चा-ठंडा टैक — हिलाते ही खुले तो वह खूँटा नहीं, धोखा है","टुकड़े कसकर भिड़ाना — \"सटे = जुड़े\" वाली उल्टी सहज-बुद्धि"),
  ("«मौसम और धातु» (पाठ-76) की सावधानी क्या है?","आँधी-बारिश में खुले में बिजली-काम पूरी तरह बंद — काम की जल्दी जान से बड़ी नहीं (पाठ-6 और पाठ-17 की आत्मा)","खड़े किनारों की मुंडेर छाती-आँख की सीध में आती है — छींटे सीधे ऊपर उछलते हैं: हेलमेट नीचे, गला-कवच ठीक (पाठ-3)","ईमानदार स्व-परीक्षा: जब आप नीचे दी गई परीक्षा या AI की परीक्षा हल करें, तो पीछे के पाठ खोलकर नक़ल न करें","खाने-दवा-बच्चों से छूने वाले काम में धातु-दर्जे पर मोल-भाव पूरी तरह बंद — वहाँ सस्ती पर्ची बनती ही नहीं"),
  ("तेज़-दोहराव: पाठ-76 («मौसम और धातु») का एक सूत्र?","बरसात = ज़ंग-ऋतु: हवादार ढँकाई, छड़-पहरा, गीले पर बिजली-सख़्ती","तिकड़ी-अदालत: करंट → चाल → कोण — तीनों जाँचे बिना फ़ैसला नहीं","वाल्व बंद करने के बाद भी सुई गिरे, तो समझें पाइप में रिसाव है","केबल की कटिंग, प्लग की हालत और सेफ्टी गार्ड को ध्यान से देखें"),
]
L[77]=[
  ("«नक़ली/घटिया लोहे की पहचान» (पाठ-77) की मुख्य बात?","घटिया या नक़ली लोहा कारीगर की साख और ग्राहक की जान दोनों के लिए ख़तरनाक है","सीधी लकीर वेल्डर की वर्णमाला का पहला अक्षर है, और उसकी कॉपी की लाइन चॉक-रेखा","धातु और वेल्डिंग छड़ की सही जोड़ी बनाना वेल्डिंग की सबसे बुनियादी जरूरत है","जीआई (GI) यानी जस्ता चढ़ी चादर लोहे को ज़ंग से बचाने के लिए बहुत बढ़िया है"),
  ("पाठ-77 «नक़ली/घटिया लोहे की पहचान» में आम ग़लती?","पूरी खेप को एक-सा मान लेना — डीलर अक्सर ऊपर की दो डंडियाँ असली ब्रांड की रखते हैं और नीचे घटिया माल छुपा देते हैं","सिर्फ़ \"मोटा लगा देंगे\" का भरोसा बेचना: इससे ग्राहक का पैसा और ढाँचे का वज़न बढ़ता है, लेकिन असली ताक़त नहीं बढ़ती","गलत पोलैरिटी (Polarity) चुनना: अगर डीसी (DC) वेल्डिंग करते समय आपने टॉर्च को प्लस (+) वाले टर्मिनल में जोड़ दिया","काम के बाद नंगे लोहे को ऐसे ही छोड़ देना: बिना ज़ंग-रोधी पेंट के वह जगह कुछ ही दिनों में ज़ंग खाकर कमज़ोर हो जाएगी"),
  ("कौन-सी ग़लती «नक़ली/घटिया लोहे की पहचान» वाले पाठ-77 में बताई गई?","बिना बिल का माल लेना — 'सस्ता पड़ेगा' सोचकर बिना पर्ची के माल उठाना","जंग-रंग-तेल के ऊपर क्लैंप — छुआ है, जुड़ा नहीं; पहले रेती की दो रगड़","\"गरमी बहुत है, बनियान में कर लेता हूँ।\" — किरण को मौसम से मतलब नहीं","\"थोड़ी देर का ही तो ग्राइंडर है।\" — बूँद भी थोड़ी देर की ही होती है"),
  ("«नक़ली/घटिया लोहे की» (पाठ-77) की सावधानी क्या है?","घटिया निकला माल कभी भी ऐसे कामों में इस्तेमाल न करें जहाँ जान का जोखिम हो (जैसे झूला, सीढ़ी, छत की रेलिंग, या भारी छज्जा)","माइल्ड स्टील नरम है, पर उसकी कटी हुई धार और किनारे उतने ही तीखे हैं — दस्ताने का नियम (पाठ-4) धातु देखकर ढीला नहीं पड़ता","पटरे को क्लैंप से दबाइए, हाथ से थामकर नहीं — वह गरमी चूसने वाला तकिया है, यानी ख़ुद तपता है: हटाते समय दस्ताना और सोच","टैक तोड़ते समय छेनी की चोट से धातु-कण उछलते हैं — चश्मा अनिवार्य (पाठ-27), और चोट की दिशा अपने व साथी के बदन से हटाकर"),
  ("तेज़-दोहराव: पाठ-77 («नक़ली/घटिया लोहे की») का एक सूत्र?","तौल झूठ नहीं बोलती","चढ़ाई ≥ चौड़ी उँगली","पायँचा जूते के ऊपर","रुई शोर नहीं रोकती"),
]
L[78]=[
  ("पाठ-78 («धातु और मज़बूती कौन») का सार क्या है?","लोहे की मज़बूती केवल उसकी मोटाई पर निर्भर नहीं करती, बल्कि उसके आकार और सही बनावट पर टिकी होती है","दुर्घटना का आधा हिस्सा मशीन से नहीं, बिखरी जगह से आता है — इसलिए वेल्डर की दुकान रसोई की तरह सजती है","पुराना लोहा बूढ़ा मरीज़ है — पहले ठक-ठक और खुरचन से नाड़ी देखो: ऊपर की मैल है या भीतर तक खाया घुन","इस पाठ में हमने पिछले तीस पाठों (पाठ 51 से 79) के धातु-ज्ञान का पूरा निचोड़ पाँच गिरहों में समझा"),
  ("«धातु और मज़बूती कौन» (पाठ-78) की आम ग़लती क्या है?","सिर्फ़ \"मोटा लगा देंगे\" का भरोसा बेचना: इससे ग्राहक का पैसा और ढाँचे का वज़न बढ़ता है, लेकिन असली ताक़त नहीं बढ़ती","हर काम के लिए एक ही मशीन को बेस्ट मानना: यह सोचना कि टिग वेल्डिंग सबसे महँगी है तो वह हर काम के लिए सबसे अच्छी होगी","काम के बाद नंगे लोहे को ऐसे ही छोड़ देना: बिना ज़ंग-रोधी पेंट के वह जगह कुछ ही दिनों में ज़ंग खाकर कमज़ोर हो जाएगी","शोर-भरी दुकान में आवाज़-जाँच छोड़ देना — शोर ही है तो बग़ल का ग्राइंडर दो सेकंड रुकवाना सस्ता है, ख़राब जोड़ महँगा"),
  ("कौन-सी ग़लती «कौन कितना भार सहे» वाले पाठ-78 में बताई गई?","मुख्य जोड़ को भार के ठीक नीचे रखना: जहाँ सबसे ज़्यादा वज़न पड़ना हो, ठीक उसी जगह मुख्य वेल्डिंग जोड़ रखने से वह जल्दी टूट जाता है","उधार के लालच में घटिया माल लेना: कई बार कारीगर उधार खाता चलाने के चक्कर में दुकानदार का हर तरह का टेढ़ा और जंग लगा माल चुपचाप ले","टूटी हुई घुंडी से काम चलाना: कई दुकानों पर घुंडी का प्लास्टिक का ढक्कन टूट जाता है और कारीगर प्लास से पकड़कर अंदाज़े से करंट सेट","मशीन को बेकार चालू छोड़ना: यह सोचना कि \"जब वेल्डिंग नहीं हो रही तो बिल क्यों आएगा।\" मशीन का पंखा और अंदरूनी पुर्ज़े चालू रहने पर"),
  ("«धातु और मज़बूती» (पाठ-78) की सावधानी क्या है?","भार के दावे में हमेशा अपनी ज़बान नपी-तुली रखें","चढ़ती लकीर में चेहरा तालाब के नीचे-सामने रहता है","खास छड़ें (जैसे SS और निकल) बहुत महँगी आती हैं","कोने की भराई में गरमी दो दीवारों के बीच घिरती है"),
  ("तेज़-दोहराव: पाठ-78 («धातु और मज़बूती») का एक सूत्र?","मोटाई आधी सच्चाई","सीधा माल आधा हुनर","जाँच बंद मशीन पर","बीच हल्का फ़ासला"),
]
L[79]=[
  ("पाठ-79 («काम के लिए सही») का सार क्या है?","अट्ठाईस पाठों की धातु-विद्या तीन सवालों की छलनी में सिमटती है","ओवरहेड सीढ़ी की चोटी है — गुरुत्व पूरा दुश्मन, हर बूँद आपकी ओर","इस पाठ में हमने सीखा कि हर औज़ार को ख़रीदना अक़्लमंदी नहीं है","नाम-पट्टी मशीन का आधार कार्ड है, और उसके तीन अंक पूरी कुंडली"),
  ("«काम के लिए सही» (पाठ-79) की आम ग़लती क्या है?","ग्राहक के \"सस्ता\" सुनते ही छलनी उलटी चलाना — जेब से शुरू किया माल उल्टा निकलता है","केबल को कसकर लपेटना: केबल को किसी खूँटी या मशीन के ऊपर ही बहुत कस-कसकर लपेट देना","झालर देखकर करंट और बढ़ाना (\"माल पहुँच नहीं रहा होगा\") — उल्टी दवा: तालाब और भारी","जाँच सिर्फ़ सोमवार को — मशीन को हफ़्ते का पता नहीं होता; केबल मंगल को भी कटती है"),
  ("कौन-सी ग़लती «धातु चुनना तीन सवाल» वाले पाठ-79 में बताई गई?","दूसरी पर्ची में घटिया माल रख देना — विकल्प दर्जे का नहीं, ढंग का","थके हाथ से \"बस यह जोड़ और\" — इस दिशा में थकान की क़ीमत सबसे महँगी","माल आगे भागने पर चाल धीमी कर देना — उलटी दवा: यहाँ तेज़ी ही इलाज","टाँका ग़ौर से देखने के लिए धारा के ठीक ऊपर झुकना — सबसे आम ग़लती"),
  ("«काम के लिए» (पाठ-79) की सावधानी क्या है?","खाने-दवा-बच्चों से छूने वाले काम में धातु-दर्जे पर मोल-भाव पूरी तरह बंद — वहाँ सस्ती पर्ची बनती ही नहीं","ईमानदार स्व-परीक्षा: जब आप नीचे दी गई परीक्षा या AI की परीक्षा हल करें, तो पीछे के पाठ खोलकर नक़ल न करें","कड़ी रोशनी से आँखों का बचाव: टीआईजी (TIG) की आर्क से निकलने वाली पराबैंगनी किरणें बहुत ही तीखी होती हैं","दिन के अंत में बाल्टी ख़ाली करने से पहले टटोलिए मत — उसमें सुबह का ठंडा और शाम का गरम, दोनों टुकड़े हैं"),
  ("तेज़-दोहराव: पाठ-79 («काम के लिए») का एक सूत्र?","छलनी का क्रम: काम → जगह → जेब — उलटी कभी नहीं","होल्डर = बिजली और हथेली के बीच की आख़िरी दीवार","झनझनाहट = ख़तरे की घंटी — मशीन बंद, पहले जाँच","जोखिम वाले कामों में घटिया माल हरगिज़ न लगाएँ"),
]
L[80]=[
  ("«हिस्सा 3 का दोहराव» (पाठ-80) की मुख्य बात?","इस पाठ में हमने पिछले तीस पाठों (पाठ 51 से 79) के धातु-ज्ञान का पूरा निचोड़ पाँच गिरहों में समझा","गैस-वेल्डिंग का सिलेंडर भारी दबाव से भरा शांत दिखने वाला साथी है, जो सम्मान यानी नियम माँगता है","चिंगारी-जाँच वेल्डर की कसौटी है — ग्राइंडर की हल्की छुअन पर माइल्ड स्टील पीली फुलझड़ी छोड़ता है","इस पाठ में हमने जाना कि लोहा केवल एक धातु नहीं, बल्कि एक बड़ा परिवार है जिसके अलग-अलग सदस्य हैं"),
  ("«धातु ज्ञान की गाँठ» (पाठ-80) की आम ग़लती क्या है?","दोहराव छोड़कर सीधे आर्क जलाने की जल्दी करना — बिना नींव के बनाया गया मकान पहली ही बारिश में ढह जाता है","अच्छे अंक पर माला छोड़ देना — ज्ञान का इम्तिहान आज हुआ; आदत का इम्तिहान बिजली, आग और थकान रोज़ लेते हैं","पतले सर्विस वायर (Service Wire) का उपयोग: लोड के हिसाब से तार पतला होने पर बिजली का बिल तो बढ़ता ही है","घुमाने का आलस — \"लिटाने में वक़्त लगेगा\" कहकर खड़े से लड़ना: लिटाने का वक़्त हमेशा झालर छीलने से सस्ता"),
  ("कौन-सी ग़लती «हिस्सा 3 का दोहराव» वाले पाठ-80 में बताई गई?","पुराने पाठों को भूल जाना — वेल्डिंग करते समय बार-बार पाठ 51 से 79 के नियम काम आएँगे, उन्हें दिमाग से ओझल न होने दें","दूसरे का हेलमेट बिना पट्टा कसे पहनना — ढीला हेलमेट टाँके के बीच सरकता है, और आदमी नंगी आँख से आर्क में झाँक बैठता है","हर काम के लिए एक ही मशीन को बेस्ट मानना: यह सोचना कि टिग वेल्डिंग सबसे महँगी है तो वह हर काम के लिए सबसे अच्छी होगी","पानी डालकर ठंडा करना: वेल्डिंग के तुरंत बाद इसे ठंडा करने के लिए इस पर पानी डाल देना इसे पूरी तरह बर्बाद कर देता है"),
  ("«धातु ज्ञान की» (पाठ-80) की सावधानी क्या है?","कल से हमारा काम सीधे हाथ का होने वाला है","खास छड़ें (जैसे SS और निकल) बहुत महँगी आती हैं","लोहे का माल बहुत भारी और नुकीला होता है","भार के दावे में हमेशा अपनी ज़बान नपी-तुली रखें"),
  ("तेज़-दोहराव: पाठ-80 («धातु ज्ञान की») का एक सूत्र?","पाँच गिरहें याद रखें: परिवार, पहचान, मिज़ाज, बाज़ार और फ़ैसला","घुंडी दाहिने घुमाने से दबाव बढ़ता है, बाएँ घुमाने से घटता है","दो पर्चियाँ, दोनों ईमानदार, लिखी हुई — ज़बान चुप, हिसाब मुखर","गरम-सूचक बत्ती जलने पर मशीन चालू रखें, पंखे को ठंडा करने दें"),
]
